# -*- coding: utf-8 -*-
"""Author content/samples/bad-al-amali — story 13, the Amali creed poem.

The Arabic verses are the RECEIVED qasida text of Siraj al-Din al-Ushi as
carried in the user's upload (research/sources/emali-qasida-ottoman.txt);
the Ottoman word-by-word commentary informs the translations, converted to
modern Turkish. One bayt = one sentence; the hemistich break rides
punctAfter («•»). Verb paradigms are copied from packages that already
carry them (paradigms are semantics-free): qala from aqaid, laysa and
radiya from the Samti wasiyya.
"""
import json, re, pathlib

ROOT = pathlib.Path(__file__).resolve().parents[2]
PKG = ROOT / "content/samples/bad-al-amali"
(PKG / "chapters").mkdir(parents=True, exist_ok=True)

DIA = re.compile("[ً-ٰ]")
def bare(s): return DIA.sub("", s)

def tok(full, lex, pos, grammar, ar, en, tr, punct=None):
    t = {"surface": {"full": full, "smart": full, "bare": bare(full)},
         "lex": lex, "pos": pos}
    if grammar: t["grammar"] = grammar
    t["irab"] = {"ar": ar, "en": en, "tr": tr}
    if punct: t["punctAfter"] = punct
    return t

J = lambda text, ar, en, tr: {"text": text, "ar": ar, "en": en, "tr": tr}

S = []

