      "مَعْطُوفٌ مَرْفُوعٌ بِضَمَّةٍ مُقَدَّرَةٍ عَلَى الْأَلِفِ — اسْمٌ مَقْصُورٌ بِمَعْنَى النِّعْمَةِ، مِثْلُ بُشْرَى.",
      "Joined, raf' by an assumed damma on the alif — a maqsur noun meaning «bliss», like «bushra».",
