# paradigms are copied, never re-authored: qala from aqaid, laysa + radiya
# from the Samti package (identity checked on the bare lemma).
def copy_verbs():
    out = {}
    for lex, src in (("qala", "aqaid-ahl-al-sunna"),
                     ("laysa", "wasiyyat-abi-hanifa-samti"),
                     ("radiya", "wasiyyat-abi-hanifa-samti"),
                     ("mada", "wasiyyat-abi-hanifa-samti"),
                     ("taala", "wasiyyat-abi-hanifa-samti"),
                     ("amata", "wasiyyat-abi-yusuf-l5"),
                     ("raa", "wasiyyat-abi-yusuf-l5"),
                     ("kana", "wasiyyat-abi-hanifa-samti"),
                     ("ata", "wasiyyat-abi-hanifa-samti"),
                     ("alima", "wasiyyat-abi-hanifa-samti"),
                     ("qada", "wasiyyat-abi-hanifa-samti"),
                     ("sara", "wasiyyat-abi-hanifa-samti")):
        verbs = json.loads((ROOT / "content/samples" / src / "morphology.json")
                           .read_text(encoding="utf-8"))["verbs"]
        e = verbs[lex]
        assert bare(e["mazi"][0]) == bare(GLOSS[lex]["lemma"]).replace("(", "").strip(), lex
        out[lex] = e
    return out

